fun main() {
    val sb = StringBuilder("hello")
    sb.append(' ').append("world")
    println(sb)
    sb.insert(5, ",")
    println(sb)
    sb.deleteCharAt(0)
    println(sb)
    sb.replace(0, 4, "J")
    println(sb)
    sb.delete(1, 3)
    println(sb)
    println(sb.indexOf("o") to sb.length)
    sb.setCharAt(0, 'X')
    println(sb[0] + sb.substring(1))
    sb.clear()
    println(sb.isEmpty())
    sb.appendLine("a").appendLine("b")
    println(sb.lines().size)
    sb.setLength(0)
    for (i in 1..3) sb.append(i).append(if (i < 3) "," else "")
    println(sb.toString())
    println(sb.reversed())
    println(StringBuilder().append(1.5f).append(2L).append(null as String?).toString())
    println(sb.contains("2"))
    println(sb.toString().toCharArray().size)
    val sb2 = StringBuilder()
    sb2.append("abc", 1, 3)
    println(sb2)
    sb2.append(charArrayOf('x', 'y'))
    println(sb2)
    println(sb2.capacity() >= sb2.length)
    println(sb2.compareTo(StringBuilder("zzz")) < 0)
    println(sb2 == sb2)
    println(sb2.equals(StringBuilder(sb2.toString())))
    println(sb2.toString() == "bcxy")
    sb2.ensureCapacity(100)
    println(sb2.length)
}
